const orderQueueFilter={search:"",status:"",source:"",facility:"",from:"",to:""};
const money=value=>'৳ '+value.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const queueBadge=value=>'<span class="order-badge order-'+esc(value.toLowerCase().replace(/\s+/g,'-'))+'">'+esc(value)+'</span>';

function renderCommerceOrderQueue(){
  const rows=commerceOrders.filter(order=>(!orderQueueFilter.search||(order.id+' '+order.customer+' '+order.phone).toLowerCase().includes(orderQueueFilter.search.toLowerCase()))&&(!orderQueueFilter.status||order.fulfillment===orderQueueFilter.status)&&(!orderQueueFilter.source||order.source===orderQueueFilter.source)&&(!orderQueueFilter.facility||order.facility===orderQueueFilter.facility)&&(!orderQueueFilter.from||order.date>=orderQueueFilter.from)&&(!orderQueueFilter.to||order.date<=orderQueueFilter.to));
  const select=(key,label,choices)=>`<label class="order-filter"><span>${label}</span><select data-order-filter="${key}" aria-label="${label}"><option value="">All ${label.toLowerCase()}</option>${choices.map(value=>`<option value="${esc(value)}" ${orderQueueFilter[key]===value?'selected':''}>${esc(value)}</option>`).join('')}</select></label>`;
  return `<div class="commerce-order-queue"><header class="commerce-order-header"><div><span class="eyebrow">Orders & POS / Operations</span><h1>Order Queue</h1><p>Track online, manual, CRM, and customer-fulfillment orders that need operational follow-up.</p></div><div class="commerce-order-actions"><a class="btn" href="#/app/ecommerce/pos">POS</a><a class="btn primary" href="#/app/ecommerce/orders/manual-sell">Manual Order <span aria-hidden="true">↗</span></a></div></header>
    <div class="order-queue-summary"><div><span>Pending</span><strong>3</strong><small>Awaiting confirmation</small></div><div><span>Processing</span><strong>1</strong><small>In fulfillment</small></div><div><span>Shipped</span><strong>1</strong><small>On the way</small></div><div><span>Delivered</span><strong>1</strong><small>Completed</small></div></div>
    <section class="commerce-order-panel"><div class="commerce-order-panel-head"><div><span class="eyebrow">Order management</span><h2>Recent orders</h2></div><div class="order-count"><strong>${rows.length}</strong> results <button type="button" data-order-clear>Clear filters</button></div></div><div class="order-filter-grid"><label class="order-filter order-search"><span>Search</span><input id="order-queue-search" data-order-filter="search" type="search" placeholder="Order number, customer, phone…" value="${esc(orderQueueFilter.search)}"></label>${select('status','Status',['Pending','Processing','Shipped','Delivered','Cancelled'])}${select('source','Source',['Online','Manual (Admin)','POS customer orders','CRM Deal'])}${select('facility','Facility',['Downtown Store','North Branch'])}<label class="order-filter"><span>From</span><input data-order-filter="from" type="date" value="${esc(orderQueueFilter.from)}"></label><label class="order-filter"><span>To</span><input data-order-filter="to" type="date" value="${esc(orderQueueFilter.to)}"></label></div>
    ${rows.length?`<div class="order-table-wrap"><table class="order-table"><thead><tr><th>Order</th><th>Customer</th><th>Source</th><th>Facility</th><th>Payment</th><th>Finance</th><th>Inventory</th><th>Total</th><th>Fulfillment</th><th aria-label="Actions"></th></tr></thead><tbody>${rows.map(order=>`<tr><td><a class="order-id" href="#/app/ecommerce/orders/${order.id}">${order.id}</a><small>${order.date} · ${order.time}</small></td><td><strong>${esc(order.customer)}</strong><small>${esc(order.phone)}</small></td><td>${esc(order.source)}</td><td>${esc(order.facility)}</td><td>${queueBadge(order.payment)}</td><td>${queueBadge(order.finance)}</td><td>${queueBadge(order.inventory)}</td><td class="order-total">${money(order.total)}</td><td>${queueBadge(order.fulfillment)}</td><td><a class="order-view" href="#/app/ecommerce/orders/${order.id}">View ↗</a></td></tr>`).join('')}</tbody></table></div><div class="order-table-footer">Showing ${rows.length} of ${commerceOrders.length} sample orders <span>Sample data · September 2026</span></div>`:`<div class="order-empty"><span aria-hidden="true">⌕</span><strong>No orders found</strong><p>Try a different search, status, source, facility, or date range.</p><button class="btn" type="button" data-order-clear>Clear filters</button></div>`}</section></div>`;
}

function renderCommerceOrderDetail(id){
  const order=commerceOrders.find(item=>item.id===id);
  if(!order)return '<div class="order-empty"><strong>Order not found</strong><a class="btn" href="#/app/ecommerce/orders/queue">Back to Order Queue</a></div>';
  const subtotal=order.items.reduce((sum,item)=>sum+item[1]*item[2],0);
  return `<div class="commerce-order-detail"><header class="commerce-order-header"><div><a class="order-back" href="#/app/ecommerce/orders/queue">← Order Queue</a><span class="eyebrow">Commerce / Order detail</span><h1>Order #${esc(order.id)}</h1><p>${esc(order.date)} · ${esc(order.time)} · ${esc(order.source)}</p></div>${queueBadge(order.fulfillment)}</header><div class="order-detail-layout"><div class="order-detail-main"><section class="commerce-order-panel"><div class="commerce-order-panel-head"><h2>Customer & Scope</h2></div><div class="order-detail-pairs"><div><span>Customer</span><strong>${esc(order.customer)}</strong></div><div><span>Phone</span><strong>${esc(order.phone)}</strong></div><div><span>Facility</span><strong>${esc(order.facility)}</strong></div><div><span>Source</span><strong>${esc(order.source)}</strong></div></div></section><section class="commerce-order-panel"><div class="commerce-order-panel-head"><h2>Addresses</h2></div><div class="order-detail-pairs"><div><span>Billing</span><strong>${esc(order.customer)} · 42 Market Street</strong></div><div><span>Shipping</span><strong>${esc(order.customer)} · 42 Market Street</strong></div></div></section><section class="commerce-order-panel"><div class="commerce-order-panel-head"><h2>Items</h2></div><div class="order-detail-items">${order.items.map(([name,quantity,price])=>`<div><span class="stock-initial">${esc(name.split(' ').map(word=>word[0]).slice(0,2).join(''))}</span><strong>${esc(name)}</strong><span>${quantity} × ${money(price)}</span><b>${money(quantity*price)}</b></div>`).join('')}</div></section><section class="commerce-order-panel"><div class="commerce-order-panel-head"><h2>Activity</h2></div><div class="order-activity"><div><span></span><strong>Order created</strong><small>${esc(order.date)} · ${esc(order.time)}</small></div><div><span></span><strong>${esc(order.payment)} payment</strong><small>Sample transaction</small></div></div></section></div><aside class="order-detail-side"><section class="commerce-order-panel"><div class="commerce-order-panel-head"><h2>Totals</h2></div><div class="order-totals"><div><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div><span>Tax, delivery & adjustments</span><strong>${money(order.total-subtotal)}</strong></div><div class="grand"><span>Total</span><strong>${money(order.total)}</strong></div></div></section><section class="commerce-order-panel"><div class="commerce-order-panel-head"><h2>Order Fulfillment</h2></div><div class="order-side-content"><p>Current status: ${queueBadge(order.fulfillment)}</p><a class="btn" href="#/app/ecommerce/orders/queue">Return to queue</a></div></section><section class="commerce-order-panel"><div class="commerce-order-panel-head"><h2>Record Payment</h2></div><div class="order-side-content"><p>Payment status: ${queueBadge(order.payment)}</p><p>Finance: ${queueBadge(order.finance)}</p></div></section><section class="commerce-order-panel"><div class="commerce-order-panel-head"><h2>Refund</h2></div><div class="order-side-content"><p>Refund controls are available in the live application.</p></div></section></aside></div></div>`;
}

root.addEventListener('input',event=>{const key=event.target.dataset.orderFilter;if(!key)return;orderQueueFilter[key]=event.target.value;if(key==='search')render(true)});
root.addEventListener('change',event=>{const key=event.target.dataset.orderFilter;if(!key)return;orderQueueFilter[key]=event.target.value;render()});
root.addEventListener('click',event=>{if(!event.target.closest('[data-order-clear]'))return;for(const key of Object.keys(orderQueueFilter))orderQueueFilter[key]='';render()});

function enhanceCommerceOrderDetail(html,id){
  const order=commerceOrders.find(item=>item.id===id);
  if(!order)return html;
  const amountDue=order.payment==='Paid'?0:order.total;
  const holder=document.createElement('template');holder.innerHTML=html;
  const rail=holder.content.querySelector('.order-detail-side');
  rail.innerHTML=`<section class="commerce-order-panel"><div class="commerce-order-panel-head"><h2>Totals</h2></div><div class="order-totals"><div><span>Subtotal</span><strong>${money(order.items.reduce((sum,item)=>sum+item[1]*item[2],0))}</strong></div><div><span>Tax, delivery & adjustments</span><strong>${money(order.total-order.items.reduce((sum,item)=>sum+item[1]*item[2],0))}</strong></div><div class="grand"><span>Total</span><strong>${money(order.total)}</strong></div><div><span>Balance due</span><strong>${money(amountDue)}</strong></div></div></section>
  ${amountDue>0?`<section class="commerce-order-panel"><div class="commerce-order-panel-head"><div><h2>Record Payment</h2><p>Balance due: ${money(amountDue)}</p></div></div><div class="order-side-content order-action-form"><label>Amount<input data-order-payment-amount type="number" min="0.01" max="${amountDue}" step="0.01" value="${amountDue.toFixed(2)}"></label><label>Tender<select data-order-payment-tender><option>Cash</option><option>Card terminal</option><option>Mobile wallet</option><option>Bank transfer</option></select></label><label>Transaction reference<input data-order-payment-reference placeholder="Optional for cash"></label><button class="btn primary" data-order-action="payment" data-order-id="${id}">Record payment</button></div></section>`:''}
  <section class="commerce-order-panel"><div class="commerce-order-panel-head"><div><h2>Order Fulfillment</h2><p>Move this order through fulfillment</p></div></div><div class="order-side-content order-action-form"><div class="order-status-summary"><span>Commercial · Confirmed</span><span>Payment · ${esc(order.payment)}</span><strong>Fulfillment · ${esc(order.fulfillment)}</strong></div><label>Next status<select data-order-next-status><option>Confirmed</option><option>Processing</option><option>Shipped</option><option>Delivered</option><option>Cancelled</option></select></label><label>Fulfillment status<select data-order-fulfillment><option value="${esc(order.fulfillment)}">Keep ${esc(order.fulfillment)}</option>${['Pending','Processing','Shipped','Delivered','Cancelled'].filter(value=>value!==order.fulfillment).map(value=>`<option>${value}</option>`).join('')}</select></label><label>Note<input data-order-note placeholder="Add a status note"></label><button class="btn primary" data-order-action="fulfillment" data-order-id="${id}">Update Status</button></div></section>
  <section class="commerce-order-panel"><div class="commerce-order-panel-head"><div><h2>Refund</h2><p>Issue a controlled refund against this order</p></div></div><div class="order-side-content order-action-form"><label>Amount<input data-order-refund-amount type="number" min="0.01" max="${order.total}" step="0.01" placeholder="0.00"></label><label>Reason<input data-order-refund-reason placeholder="Reason for refund"></label><button class="btn" data-order-action="refund" data-order-id="${id}">Issue Refund</button></div></section>`;
  if(order.sampleNotice){const note=document.createElement('div');note.className='order-sample-notice';note.setAttribute('role','status');note.textContent=order.sampleNotice;holder.content.querySelector('.commerce-order-header').after(note)}
  return holder.innerHTML;
}

root.addEventListener('click',event=>{
  const button=event.target.closest('[data-order-action]');if(!button)return;
  const order=commerceOrders.find(item=>item.id===button.dataset.orderId);if(!order)return;
  if(button.dataset.orderAction==='fulfillment'){
    order.fulfillment=root.querySelector('[data-order-fulfillment]')?.value||order.fulfillment;
    order.sampleNotice=`Sample order status updated to ${order.fulfillment}.`;
  }else if(button.dataset.orderAction==='payment'){
    const amount=Number(root.querySelector('[data-order-payment-amount]')?.value);
    if(!Number.isFinite(amount)||amount<=0||amount>order.total){order.sampleNotice='Enter a payment amount within the balance due.'}
    else{order.payment='Paid';order.finance='Synced';order.sampleNotice=`Sample payment of ${money(amount)} recorded.`}
  }else if(button.dataset.orderAction==='refund'){
    const amount=Number(root.querySelector('[data-order-refund-amount]')?.value);
    const reason=root.querySelector('[data-order-refund-reason]')?.value.trim();
    order.sampleNotice=Number.isFinite(amount)&&amount>0&&amount<=order.total&&reason?`Sample refund of ${money(amount)} recorded: ${reason}.`:'Enter a valid refund amount and reason.';
  }
  render();
});
